data = sys.stdin.read().split()
r, c, k = int(data[0]), int(data[1]), int(data[2])
g = [list(data[3 + i]) for i in range(r)]
for _ in range(k):
    change = []
    for i in range(r):
        for j in range(c):
            if g[i][j] == '1':
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = i + di, j + dj
                    if 0 <= a < r and 0 <= b < c and g[a][b] == '2':
                        change.append((i, j))
                        break
    if not change:
        break
    for i, j in change:
        g[i][j] = '2'
print('HUMANS' if any('1' in row for row in g) else 'ZOMBIES')

